import json, re, datetime
ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
MONTHS = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
CUR = [('TL', 'debtTL', 'Türk Lirası'), ('USD', 'debtUSD', 'Dolar'), ('EUR', 'debtEUR', 'Euro'), ('GBP', 'debtGBP', 'İngiliz Sterlini')]
def _w3(n):
    h, r = divmod(n, 100)
    t, o = divmod(r, 10)
    out = []
    if h:
        out.append('yüz' if h == 1 else ONES[h] + ' yüz')
    if t:
        out.append(TENS[t])
    if o:
        out.append(ONES[o])
    return ' '.join(out)
def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    out = []
    for size, name in ((10**9, 'milyar'), (10**6, 'milyon'), (1000, 'bin')):
        q, n = divmod(n, size)
        if q:
            out.append('bin' if (size == 1000 and q == 1) else _w3(q) + ' ' + name)
    if n:
        out.append(_w3(n))
    return ' '.join(out)
def money(x, code):
    cents = int(round(abs(float(x)) * 100))
    whole, frac = divmod(cents, 100)
    full = dict(TL='Türk Lirası', USD='Dolar', EUR='Euro', GBP='İngiliz Sterlini')[code]
    short = dict(TL='lira', USD='Dolar', EUR='Euro', GBP='İngiliz Sterlini')[code]
    sub = dict(TL='kuruş', USD='sent', EUR='sent', GBP='peni')[code]
    if frac == 0:
        return words(whole) + ' ' + full
    return words(whole) + ' ' + short + ' ' + words(frac) + ' ' + sub
def digits(s):
    return ' '.join(DIG[int(c)] for c in str(s) if c.isdigit())
def pdate(s):
    try:
        d, m, y = str(s).strip().split('.')
        return datetime.date(int(y), int(m), int(d))
    except Exception:
        return None
def sdate(d):
    return str(d.day) + ' ' + MONTHS[d.month] + ' ' + str(d.year)
def today_of(v):
    try:
        return datetime.date.fromisoformat(str(v.get('now') or '')[:10])
    except Exception:
        return None
def num(x):
    try:
        return float(x)
    except Exception:
        return 0.0
def env(result):
    b = result.get('data') if isinstance(result, dict) else None
    if isinstance(b, str):
        try:
            b = json.loads(b)
        except Exception:
            b = None
    if not isinstance(b, dict):
        b = dict()
    sc = result.get('status_code') if isinstance(result, dict) else None
    try:
        sc = int(sc)
    except Exception:
        sc = 0
    res = b.get('result') if isinstance(b.get('result'), dict) else dict()
    code = str(res.get('returnCode') or res.get('code') or '')
    inner = b.get('data') if isinstance(b.get('data'), dict) else None
    ok = (sc == 200 or sc == 0) and code == '1' and inner is not None
    return ok, sc, code, inner, b
def V():
    try:
        return vars
    except Exception:
        return dict()
def setv(k, val):
    try:
        vars[k] = val
    except Exception:
        pass
def out(result, d):
    try:
        result.pop('header', None)
        result['data'] = d
    except Exception:
        pass
ERR = 'Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum.'
WERR = 'Şu anda hesap kesim tarihinizi değiştiremiyorum, sizi müşteri temsilcimize aktarıyorum.'

def args_scan(names):
    vv = V()
    b = config.get('body') if isinstance(config, dict) else None
    pools = []
    if isinstance(b, dict):
        if isinstance(b.get('data'), dict):
            pools.append(b.get('data'))
        pools.append(b)
    for n in names:
        for p in pools:
            x = p.get(n)
            if x not in (None, '') and not (isinstance(x, str) and x.startswith('{' + '{')):
                return x
        for k in list(vv.keys()):
            if k.endswith('_args.' + n) or k.endswith('_args.data.' + n) or k == n:
                x = vv.get(k)
                if x not in (None, '') and not (isinstance(x, str) and x.startswith('{' + '{')):
                    return x
    return None
def setbody(data):
    try:
        config['body'] = dict(data=data, call=dict(ani='', lang='tr'))
        h = config.get('headers') if isinstance(config.get('headers'), dict) else dict()
        h['Content-Type'] = 'application/json'
        config['headers'] = h
    except Exception:
        pass
def cards():
    vv = V()
    try:
        c = json.loads(vv.get('cards_json') or '[]')
        if c:
            return c
    except Exception:
        pass
    found = dict()
    for k, val in list(vv.items()):
        m = re.search(r'cards\.(\d+)\.(cardNumber|cardNumberLast4|productName|isMainCard)$', str(k))
        if m:
            found.setdefault(int(m.group(1)), dict())[m.group(2)] = val
    return [found[i] for i in sorted(found)]

try:
    want = ''
    cl = cards()
    try:
        idx = int(1)
        if idx == 0:
            mm = [c for c in cl if str(c.get('isMainCard')).lower() != 'false']
            if mm:
                want = str(mm[0].get('cardNumber'))
        if 1 <= idx <= len(cl):
            want = str(cl[idx - 1].get('cardNumber'))
    except Exception:
        pass
    pick = None
    for c in cl:
        if str(c.get('cardNumber')) == want:
            pick = c
    if pick is None and want:
        dg = re.sub(r'\D', '', want)
        if dg:
            cand = [c for c in cl if re.sub(r'\D', '', str(c.get('cardNumber'))).endswith(dg[-4:]) and (len(dg) <= 4 or str(c.get('cardNumber'))[:6] == dg[:6] or len(dg) < 16)]
            if len(dg) > 4 and len(dg) < 16:
                cand = [c for c in cand if re.sub(r'\D', '', str(c.get('cardNumber')))[-len(dg):].replace('*', '') == dg[-len(dg):] or True]
            if len(cand) >= 1:
                pick = cand[0]
        if pick is None:
            nm = [c for c in cl if str(c.get('productName') or '').strip().lower() == want.lower()]
            if len(nm) == 1:
                pick = nm[0]
    if pick is None and len(cl) == 1:
        pick = cl[0]
    cn = str(pick.get('cardNumber')) if pick else want
    setv('sel_card', cn)
    setbody(dict(cardNumber=cn))
except Exception:
    pass

