        for code3, key, full in CUR:
            blk = d.get(key)
            if isinstance(blk, dict) and len(blk) > 0:
                blocks.append((code3, full, blk))
        debtcur = [x for x in blocks if num(x[2].get('remainingDebt')) > 0]
        setv('pdf_currency', debtcur[0][0] if debtcur else 'TL')
        parts = []
        mode = 'normal'
        def totals():
            t = []
            for code3, full, blk in blocks:
                if num(blk.get('totalDebt')) > 0:
                    t.append(full + ' cinsinden toplam borcunuz ' + money(blk.get('totalDebt'), code3) + '.')
            if not t:
                t.append('Toplam borcunuz bulunmamaktadır.')
            return t
