        def nodebt_sentence(clear):
            names = [x[1] for x in clear]
            if not names:
                return []
            if len(names) == 1:
                s = names[0]
            else:
                s = ', '.join(names[:-1]) + ' ve ' + names[-1]
            return [s + ' borcunuz bulunmamaktadır.']
        if st is None:
            mode = 'new_card'
            parts.append(head + 'ın henüz kesilmiş bir ekstresi olmadığı için ekstre borcunuz bulunmamaktadır.')
            if nst:
                parts.append('İlk hesap kesim tarihiniz ' + sdate(nst) + ' olacak.')
        elif today and (today == nst or today == st):
            mode = 'cut_day'
            parts.append('Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek.')
            parts.append(head + 'a ait güncel borç bilgileriniz şöyle:')
            parts += totals()
        elif today and due and today > due and str(d.get('statementPaymentStatus')).upper() != 'NO_DEBT' and debtcur:
            mode = 'after_due'
            parts.append(head + 'a ait ' + sdate(st) + ' tarihinde kesilen ekstrenin son ödeme tarihi ' + sdate(due) + ' geçmiştir.')
            parts += totals()
            parts += autopay()
        elif str(d.get('statementPaymentStatus')).upper() == 'NO_DEBT' or not debtcur:
            mode = 'no_debt'
            s = head + 'ın ' + sdate(st) + ' tarihli ekstresinden borcunuz bulunmamaktadır.'
            tl = d.get('debtTL') if isinstance(d.get('debtTL'), dict) else dict()
            g = num(tl.get('totalDebt'))
            if g > 0:
                s += ' Gelecek dönemler dahil toplam borcunuz ' + money(g, 'TL') + '.'
            if due:
                s += ' Son ödeme tarihiniz ' + sdate(due) + ' olacaktır.'
            parts.append(s)
        else:
            first = True
            for code3, full, blk in blocks:
                if num(blk.get('remainingDebt')) <= 0:
                    continue
                pre = (head + 'a ait ' + sdate(st) + ' tarihinde kesilen ekstre ') if first else ''
                first = False
                X = money(blk.get('statementDebt'), code3)
                Z = money(blk.get('minPayment'), code3)
                Y = money(blk.get('remainingDebt'), code3)
                T = money(blk.get('remainingMinPayment'), code3)
                if code3 == 'TL':
                    rm = num(blk.get('remainingMinPayment'))
                    mp = num(blk.get('minPayment'))
                    if rm > 0 and rm >= mp:
                        parts.append(pre + 'Türk Lirası borcunuz ' + X + ', ödenmesi gereken minimum tutar ' + Z + '.')
                    elif rm <= 0:
                        parts.append(pre + 'Türk Lirası borcunuz ' + X + ', kalan toplam borcunuz ' + Y + '. Minimum ödemenizi yaptığınız için teşekkür ederiz.')
                    else:
                        parts.append(pre + 'Türk Lirası borcunuz ' + X + ', ödenmesi gereken minimum tutar ' + Z + ', kalan toplam borcunuz ' + Y + ', kalan minimum ödeme tutarınız ' + T + '.')
                else:
                    parts.append(pre + full + ' borcunuz ' + X + ', kalan toplam borcunuz ' + Y + ', ödenmesi gereken minimum tutar ' + Z + '.')
            clear = [x for x in blocks if num(x[2].get('remainingDebt')) <= 0]
            parts += nodebt_sentence(clear)
            if due and today and due == today:
                parts.append('Borçlarınız için son ödeme tarihiniz bugündür.')
            elif due:
                parts.append('Borçlarınız için son ödeme tarihiniz ' + sdate(due) + '.')
        reading = ' '.join(parts)
        setv('last_reading', reading)
        setv('entry_tts', reading + (' Sizi ana menüye yönlendiriyorum.' if mode in ('no_debt', 'new_card') else ''))
        setv('entry_instruction', 'Selam vermeden şu borç metnini kelimesi kelimesine aynen oku: "' + reading + '" Ardından contact_email_get aracını çağır ve sonucuna göre teklifi yap.' if mode not in ('no_debt', 'new_card') else 'Selam vermeden şu metni aynen oku: "' + reading + '" Ardından: "Sizi ana menüye yönlendiriyorum."')
        setv('balance_mode', mode)
        try:
            seen = json.loads(vv.get('cards_read') or '[]')
        except Exception:
            seen = []
        if sel and sel not in seen:
            seen.append(sel)
        setv('cards_read', json.dumps(seen))
        try:
            ncards = len([c for c in json.loads(vv.get('cards_json') or '[]') if str(c.get('isMainCard')).lower() != 'false'])
        except Exception:
            ncards = 1
        more = ncards > 1 and len(seen) < ncards
        if more:
            nxt = 'Okumadan sonra (müşteri sadece tek bir bilgi istediyse yalnızca onu söyle) AYNI cevapta şunu sor: "Başka bir kartınızın borcunu öğrenmek ister misiniz?" Evet derse kart seçimine dön. Hayır derse contact_email_get aracını çağır ve sonra teklifi yap.'
        elif mode in ('no_debt', 'new_card'):
            nxt = 'Okumadan sonra, başka kart yoksa: "Sizi ana menüye yönlendiriyorum." (Müşteri yine de e-posta veya hesap kesim değişikliği isterse yardımcı ol.)'
        else:
            nxt = 'Okumadan hemen sonra, teklif yapmadan önce contact_email_get aracını çağır (daha önce çağırmadıysan) ve ardından yalnızca yapılabilecekleri teklif et.'
        out(result, dict(ok=True, reading_to_say_verbatim=reading, what_to_do_next='Kart adını/numarasını teyit etmeden, reading_to_say_verbatim metnini kelimesi kelimesine aynen oku (rakam ya da kod kullanma). ' + nxt))
except Exception:
    pass

